INSERT  IGNORE INTO `products` (`id`, `category_id`, `name`, `slug`, `sku`, `short_description`, `description`, `specifications`, `price`, `compare_price`, `stock`, `low_stock_threshold`, `has_variants`, `is_active`, `is_featured`, `is_new`, `is_bestseller`, `is_trending`, `badge`, `sold_count`, `is_sample`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES (17,13,'T-shirt KNA-2400/01','t-shirt-kna-240001','KNA-2400/01','Fabric: Single Jersey 76% Polyester 19% Viscose 5% Spandex GSM: 160 · Cool, Soft & breathable knitted fabric · Moisture wicking technology keeps you cool and dry · Tag-free to prevent irritation · Classic length for easy tucking · Durable stitching','<p>Fabric: Single Jersey 76% Polyester 19% Viscose 5% Spandex GSM: 160<br>\nCool, Soft &amp; breathable knitted fabric<br>\nMoisture wicking technology keeps you cool and dry<br>\nTag-free to prevent irritation<br>\nClassic length for easy tucking<br>\nDurable stitching<br>\nWe made customize styles according to customer requirement/designs, fabric description, prints, embroidery etc.<br>\nPrint: We have different kind of printing techniques like direct screen print, heat transfer print, sublimation print, vinyl sticker print, DTF prints, 3D Print, digital printing etc.<br>\nEmbroidery: We have in house facility of 2 Burdan Embroidery Machine<br>\nSizes: All size range available on customer demand, Adults and youth,<br>\nEuropean sizes, American sizes and Asian Sizes</p>',NULL,0,NULL,13,3,0,1,1,0,0,0,NULL,0,0,NULL,NULL,'2026-11-11 04:30:09','2026-11-11 04:56:13',NULL),(18,13,'T-shirt KNA-2400/02','t-shirt-kna-240002','KNA-2400/02','Fabric: Single Jersey 76% Polyester 19% Viscose 5% Spandex GSM: 160 · Cool, Soft & breathable knitted fabric · Moisture wicking technology keeps you cool and dry · Tag-free to prevent irritation · Classic length for easy tucking · Durable stitching','<p>Fabric: Single Jersey 76% Polyester 19% Viscose 5% Spandex GSM: 160<br>\nCool, Soft &amp; b